mapper.update:
UPDATE goal_item
SET is_completed = #{completed}
WHERE id = #{goalItemId}
  AND goal_id = #{goalId}

mapper.select:
SELECT u.id AS userId, u.name AS name, u.role AS role, u.profile_image AS profileImage, u.is_shared AS assetShared,
COALESCE(( SELECT SUM(latest.after_transaction_balance) FROM ( SELECT ar.account_id, ar.after_transaction_balance, ROW_NUMBER() OVER ( PARTITION BY ar.account_id ORDER BY ar.transaction_date DESC, ar.transaction_time DESC, ar.id DESC ) AS rn FROM account_record ar INNER JOIN account acc ON acc.id = ar.account_id WHERE acc.user_id = u.id ) latest WHERE latest.rn = 1 ), 0) AS assetAmount, COALESCE(u.wedding_fund, 0) AS weddingFund,
COALESCE(u.wedding_fund, 0) + COALESCE(( SELECT SUM(sr.amount) FROM service_record sr WHERE sr.user_id = u.id AND sr.type = 'SAVING' AND COALESCE(sr.changed_category, sr.category) IN
#{category}
), 0) AS savingAmount FROM user u WHERE u.id IN (#{groomId}, #{brideId}) ORDER BY CASE WHEN u.id = #{groomId} THEN 0 ELSE 1 END

SELECT MIN(sr.record_date) FROM service_record sr WHERE sr.user_id IN
#{userId}
AND sr.type = 'SAVING' AND COALESCE(sr.changed_category, sr.category) IN
#{category}

SELECT COALESCE(sr.changed_category, sr.category) AS categoryCode, COALESCE(SUM(sr.amount), 0) AS expenseAmount FROM service_record sr WHERE sr.user_id IN
#{userId}
AND sr.type = 'EXPENSE' AND COALESCE(sr.changed_category, sr.category) IN
#{category}
GROUP BY COALESCE(sr.changed_category, sr.category)

SELECT DATE_FORMAT(sr.record_date, '%Y-%m') AS yearMonth, COALESCE(SUM(sr.amount), 0) AS expenseAmount FROM service_record sr WHERE sr.user_id IN
#{userId}
AND sr.type = 'SAVING' AND COALESCE(sr.changed_category, sr.category) IN
#{category}
AND sr.record_date BETWEEN #{startAt} AND #{endAt} GROUP BY DATE_FORMAT(sr.record_date, '%Y-%m') ORDER BY DATE_FORMAT(sr.record_date, '%Y-%m') ASC
